// Extract OAuth callback parameters from webhook
const webhookData = $input.first().json;
console.log('Full webhook data:', JSON.stringify(webhookData, null, 2));

const query = webhookData.query || {};
const code = query.code;
const state = query.state; // This contains company_id
const error = query.error;

console.log('Extracted code:', code);
console.log('Extracted company_id (state):', state);

// Handle OAuth errors
if (error) {
  throw new Error(`OAuth error: ${error} - ${query.error_description || ''}`);
}

// Validate code exists
if (!code) {
  throw new Error('No authorization code received from Google');
}

// Validate company_id exists
if (!state) {
  throw new Error('No company_id received in state parameter');
}

// IMPORTANT: redirect_uri must EXACTLY match what was used in the initial OAuth request
const redirectUri = 'http://localhost:5678/webhook/oauth-connect';

console.log('Using redirect_uri:', redirectUri);
console.log('Company ID:', state);

// Return data for token exchange
return {
  code: code,
  company_id: state, // company_id from state parameter
  redirect_uri: redirectUri
};

// Get Google OAuth credentials
// Note: process.env is not available in n8n Code nodes sandbox
// Reading from the credentials JSON file structure
// Values match scombinator_creditional_google_oauth.json and docker-compose.yml
const credentials = {
  client_id: '407115728261-22odd5dsa5grrtmdqena19bs5id0l0a5.apps.googleusercontent.com',
  client_secret: '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'
};

// Validate credentials exist
if (!credentials.client_id || !credentials.client_secret) {
  throw new Error('Google OAuth credentials not configured');
}

// Get data from previous node
const data = $input.first().json;

console.log('=== TOKEN EXCHANGE REQUEST ===');
console.log('Code:', data.code);
console.log('Redirect URI:', data.redirect_uri);
console.log('Company ID:', data.company_id);
console.log('Client ID loaded:', !!credentials.client_id);
console.log('Client Secret loaded:', !!credentials.client_secret);

// Return data with credentials
return {
  ...data,
  client_id: credentials.client_id,
  client_secret: credentials.client_secret
};

// Extract tokens from Google OAuth response
const tokenResponse = $input.first().json;

// Check if token exchange failed (error response)
if (tokenResponse.error) {
  throw new Error(`Token exchange failed: ${tokenResponse.error} - ${tokenResponse.error_description || ''}`);
}

// Validate token response
if (!tokenResponse || !tokenResponse.access_token) {
  throw new Error('Failed to get access token. Response: ' + JSON.stringify(tokenResponse));
}

// Get company_id from previous node
const previousData = $('Extract OAuth Code').item.json;
const companyId = previousData.company_id;

if (!companyId) {
  throw new Error('Company ID not found in previous node data');
}

// Extract token data
const accessToken = tokenResponse.access_token;
const refreshToken = tokenResponse.refresh_token || '';
const expiresIn = tokenResponse.expires_in || 3600;

// Validate access token is not empty
if (!accessToken || accessToken.trim() === '') {
  throw new Error('Access token is empty or invalid');
}

// Generate credential ID
const credentialId = 'google_cred_' + Date.now();

console.log('=== EXTRACTED TOKEN DATA ===');
console.log('Company ID:', companyId);
console.log('Access token length:', accessToken.length);
console.log('Refresh token exists:', !!refreshToken);
console.log('Expires in:', expiresIn);

// Return data for backend call
return {
  company_id: companyId,
  access_token: accessToken,
  refresh_token: refreshToken,
  expires_in: expiresIn,
  n8n_credential_id: credentialId
};
